mapper.select:
SELECT pf.id AS id, pfd.id AS detailId, pf.bill_date AS billDate, pf.code, pf.handover_no AS handoverNo, pf.platform_package_no AS platformPackageNo, pf.logistics_supplier_id AS logisticsSupplierId, pf.logistics_supplier_name AS logisticsSupplierName, pf.transport_no AS transportNo, pf.total_package_qty AS totalPackageQty, pf.total_package_weight AS totalPackageWeight, pf.weight_unit AS totalPackageWeightUnit, pf.upload_status AS uploadStatus, pf.print_status AS printStatus, pf.handover_status AS handoverStatus, pf.remark, pf.create_user_name AS createUserName, pf.create_time AS createTime, pfd.so_id AS soId, pfd.so_code AS soCode, pfd.logistics_channel_id AS logisticsChannelId, pfd.logistics_channel_name AS logisticsChannelName, pfd.track_no AS trackNo, pfd.transport_no AS minPackageTransportNo, pfd.weight, pfd.weight_unit AS weightUnit, pfd.handover_status AS minPackageHandoverStatus FROM package_forecast pf INNER JOIN package_forecast_detail pfd ON pf.id = pfd.main_id AND pfd.is_deleted = FALSE WHERE ${params.sqlMap.default}
and pf.is_deleted = FALSE
${params.permissionSql}
ORDER BY pf.create_time DESC

SELECT pf.id AS id, pfd.id AS detailId, pf.bill_date AS billDate, pf.code, pf.handover_no AS handoverNo, pf.platform_package_no AS platformPackageNo, pf.logistics_supplier_id AS logisticsSupplierId, pf.logistics_supplier_name AS logisticsSupplierName, pf.transport_no AS transportNo, pf.total_package_qty AS totalPackageQty, pf.total_package_weight AS totalPackageWeight, pf.weight_unit AS totalPackageWeightUnit, pf.upload_status AS uploadStatus, pf.print_status AS printStatus, pf.handover_status AS handoverStatus, pf.remark, pf.create_user_name AS createUserName, pf.create_time AS createTime, pfd.so_id AS soId, pfd.so_code AS soCode, pfd.logistics_channel_id AS logisticsChannelId, pfd.logistics_channel_name AS logisticsChannelName, pfd.track_no AS trackNo, pfd.transport_no AS minPackageTransportNo, pfd.weight, pfd.weight_unit AS weightUnit, pfd.handover_status AS minPackageHandoverStatus FROM package_forecast pf LEFT JOIN package_forecast_detail pfd ON pf.id = pfd.main_id AND pfd.is_deleted = FALSE WHERE pf.is_deleted = FALSE
AND pfd.id IN
#{id}
and pf.upload_status = #{uploadStatus}
and pf.code ILIKE concat('%',#{params.code}::text,'%')
and pf.logistics_supplier_id IN
#{item}
and pf.transport_no ILIKE concat('%',#{params.code}::text,'%')
and (pf.handover_no ILIKE concat('%',#{params.platformNo}::text,'%') OR pf.platform_package_no ILIKE concat('%',#{params.platformNo}::text,'%'))
and pf.handover_status IN
#{item}
and pfd.handover_status IN
#{item}
and pf.upload_status IN
#{item}
and pf.create_user_id IN
#{item}
AND pf.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > pf.create_time
${params.permissionSql}
ORDER BY pf.create_time DESC
